INSERT OR REPLACE INTO cv_records (id, message_id, sender_email, sender_name, subject, received_date, candidate_name, candidate_email, candidate_phone, candidate_city, category, seniority, experience_years, key_skills, summary, portfolio_links, file_name, file_path, preview_token, status, reported, created_at, pros, cons, cover_letter) VALUES (46, '<CAMBB4oYeajzWv5FJEGY7PvvjgGE-vuAmzkTUAdm38M8cyoZfAA@mail.gmail.com>_20261102_133955_21e766_Mehmet_Ali_Gürpınar_CV_-_ODTÜ', 'gurpinarmehmetali6@gmail.com', 'Mehmet Ali Gürpınar', 'Jr. Strategist İş Başvurusu - Mehmet Ali Gürpınar', 'Sun, 1 Nov 2026 08:00:00 +0300', 'Mehmet Ali Gürpınar', 'gurpinarmehmetali6@gmail.com', '0531 925 2887', 'İstanbul', 'Strateji ve Dijital Pazarlama', 'Junior', '1 Yıl', 'Marka Stratejisi, Pazar Araştırması, Veri Analizi, Meta Business Suite, Google Ads, Power BI', 'Aday, strateji disiplini için gerekli olan temel araçlara ve analitik bakış açısına sahip görünmektedir. Ancak, CV''deki tarihsel tutarsızlıklar ve kısa süreli iş deneyimleri, adayın profesyonel olgunluğunun ve uzun vadeli bağlılığının mülakatta detaylıca sorgulanmasını gerektirmektedir.', 'https://www.linkedin.com/in/mehmet-ali-gürpınar-b865a221a/', 'Mehmet Ali Gürpınar CV - ODTÜ.pdf', 'E:\cv-system\storage\cvs\20261102_133955_21e766_Mehmet_Ali_Gürpınar_CV_-_ODTÜ.pdf', '54d10dbd7167f7c3494a12e2202f7383', 'processed', 1, '2026-11-02 10:40:00', ' • FMCG ve finans gibi farklı sektörlerdeki markalarla çalışma deneyimi, veri odaklı strateji geliştirme yetkinliği ve vaka yarışmalarındaki başarılarıyla kanıtlanmış analitik düşünme becerisi.', ' • Kariyerinin henüz çok başında olması nedeniyle stratejik derinliğinin test edilmesi gerekir; ayrıca CV''de belirtilen bazı projelerin ve eğitimlerin tarihleri (2026 gelecek tarihli) tutarsızlık göstermektedir.', 'Merhaba,

Umarım iyisinizdir. Nabulu Reklam Ajansı Jr. Strategist pozisyonu ile
yakından ilgileniyorum. ODTÜ Uluslararası İlişkiler bölümünden mezun oldum.
Kariyerimi tamamen marka stratejisi, tüketici içgörüleri ve pazarlama
dinamikleri üzerine inşa ettim. İlgili pozisyon için uygunluğumu
değerlendirebilmeniz adına CV''mi ekte sunuyorum.

Mevcut ajans deneyimimde strateji stajyeri olarak başladığım ve Jr.
Strategist olarak devam ettiğim süreçte; kampanya stratejilerinin
oluşturulması, rakip ve sosyal medya analizi, pazar araştırmaları gibi
konularda aktif sorumluluklar aldım.

Deneyimlerimi ve ajansınızın vizyonuna sağlayabileceğim katkıları
detaylandırmak üzere sizinle tanışmaktan büyük memnuniyet duyarım. Zaman
ayırdığınız ve değerlendirdiğiniz için teşekkür ederim.

Saygılarımla,

*Mehmet Ali Gürpınar*');
INSERT OR REPLACE INTO cv_records (id, message_id, sender_email, sender_name, subject, received_date, candidate_name, candidate_email, candidate_phone, candidate_city, category, seniority, experience_years, key_skills, summary, portfolio_links, file_name, file_path, preview_token, status, reported, created_at, pros, cons, cover_letter) VALUES (47, '<CAKshzO9-aucXyg-tUu=MNv2-dMY8m51pSXJ6ZJKRS4f+YLP4eg@mail.gmail.com>_20261102_134001_a47af4_Berkay_Karabulut_CV_.pdf', 'bulutkaraberkay@gmail.com', 'Berkay Karabulut', 'İş başvurusu Hk.', 'Mon, 2 Nov 2026 11:51:54 +0300', 'Berkay Karabulut', 'bulutkaraberkay@gmail.com', '0541 815 51 39', 'İstanbul', 'Reklam Yazarlığı ve Dijital İçerik Üretimi', 'Mid-Level', '9 Yıl', 'Metin Yazarlığı, Dijital İçerik Üretimi, Senaryo Yazımı, Sosyal Medya Yönetimi, Kurumsal İletişim', 'Berkay, içerik üretimi ve metin yazarlığı konusunda geniş bir yelpazeye sahip olsa da, ajansın beklediği kampanya odaklı derinlik ve istikrarlı ajans tecrübesi konusunda eksiklikler barındırıyor. Teknik yetkinlikleri içerik üretimi için uygun görünse de, Nabulu''nun operasyonel hızı ve stratejik beklentileriyle uyumu için detaylı bir mülakat ve portfolyo incelemesi şarttır.', 'https://www.behance.net/berkaykarabulut, https://www.linkedin.com/in/berkay-karabulut-0749286b/', 'Berkay Karabulut CV_.pdf.pdf', 'E:\cv-system\storage\cvs\20261102_134001_a47af4_Berkay_Karabulut_CV_.pdf.pdf', '7365e18263576e5ff92ef41213c37122', 'processed', 1, '2026-11-02 10:40:04', ' • Farklı mecralarda (tiyatro, dijital içerik, kurumsal iletişim) metin yazarlığı deneyimi bulunması
 • İçerik üretim süreçlerinde yönetmenlik ve kurgu aşamalarına hakimiyet
 • Çeşitli sektörlerden markalarla çalışma pratiği', ' • CV''de iş tanımları ve sorumluluklar oldukça genel ifade edilmiş, somut başarı metrikleri eksik
 • Freelance ve farklı alanlardaki dağınık çalışma geçmişi, ajansın yoğun operasyonel temposuna adaptasyon konusunda soru işareti yaratıyor
 • Portfolyo içeriği, ajansın beklediği 360 derece kampanya kurgusunu kanıtlayacak derinlikte değil', 'Uzun bir süredir reklam yazarlığı yapıyorum.
Shell, Yurtbay Seramik, Turkcell, Nissan,Tat, Beyoğlu Çikolata gibi global
ve köklü bir çok markanın creative metinlerini ortaya çıkardım.

Metni bana ait olan Öğrenci Evi Youtube içeriğinin de yönetmenliğini
yapıyorum.

Birçok hacimli markalarınıza creative projeler ortaya koyabileceğimi
düşünüyorum.

İyi fikrin peşinde koşup markaları 360 derece düşünmek özetle ekibinizle
mümkün olabilir.

Güncel cv ekte. Sizinle paylaşıyorum.

Cv içerisinde portfolyoma ulaşabilirsiniz.

Güzel bir gün dilerim size');
